func TestRenderGithubSetupWorkflow(t *testing.T) {
	workflow := renderGithubSetupWorkflow("api", "acme/api", "release/canary", githubSetupRolloutStandard)
	for _, want := range []string{
		"generated by `gregale github setup`",
		"branches:\n      - \"release/canary\"",
		"poyrazK/faas/.github/actions/deploy@v0",
		`wait: "true"`,
		"PR previews are managed by the connected GitHub integration.",
	} {
		if !strings.Contains(workflow, want) {
			t.Errorf("workflow does not contain %q:\n%s", want, workflow)
		}
	}
	if strings.Contains(workflow, "pull_request:") {
		t.Fatal("production workflow must not deploy on pull_request events")
	}
	if strings.Contains(workflow, `rollout: "safe"`) {
		t.Fatal("standard production workflow must not opt into safe rollout")
	}
}

func TestRenderGithubSetupWorkflowSafeRollout(t *testing.T) {
	workflow := renderGithubSetupWorkflow("api", "acme/api", "main", githubSetupRolloutSafe)
	for _, want := range []string{
		"# Balanced health-gated rollout; available on Pro/Scale.",
		`rollout: "safe"`,
		`wait: "true"`,
	} {
		if !strings.Contains(workflow, want) {
			t.Errorf("safe workflow does not contain %q:\n%s", want, workflow)
		}
	}
}

func TestValidGithubSetupRollout(t *testing.T) {
	for _, tc := range []struct {
		value string
		want  bool
	}{
		{githubSetupRolloutStandard, true},
		{githubSetupRolloutSafe, true},
		{"", false},
		{"balanced", false},
	} {
		if got := validGithubSetupRollout(tc.value); got != tc.want {
			t.Errorf("validGithubSetupRollout(%q) = %t, want %t", tc.value, got, tc.want)
		}
	}
}

func TestGithubSetupPreviewServicePolicy(t *testing.T) {
	for _, tc := range []struct {
		value string
		want  bool
	}{
		{githubSetupPreviewServicesDeny, true},
		{githubSetupPreviewServicesAllowMarked, true},
		{"allow", false},
		{"", false},
	} {
		if got := validGithubSetupPreviewServicePolicy(tc.value); got != tc.want {
			t.Errorf("validGithubSetupPreviewServicePolicy(%q) = %t, want %t", tc.value, got, tc.want)
		}
	}
	patch := githubSetupPolicyPatch(false, false, 0, "", nil, githubSetupPreviewServicesDeny)
	if patch == nil || patch.PreviewServicePolicy == nil || *patch.PreviewServicePolicy != githubSetupPreviewServicesDeny {
		t.Fatalf("preview service policy patch = %+v", patch)
	}
}

func TestGithubSetupWorkflowPathRejectsEscape(t *testing.T) {
	for _, path := range []string{"/tmp/workflow.yml", "../workflow.yml", "..", "."} {
		if _, err := githubSetupWorkflowPath(path); err == nil {
			t.Errorf("githubSetupWorkflowPath(%q) accepted repository escape", path)
		}
	}
	if got, err := githubSetupWorkflowPath(".github/workflows/gregale.yml"); err != nil || got != filepath.Join(".github", "workflows", "gregale.yml") {
		t.Fatalf("valid workflow path = %q, err = %v", got, err)
	}
}

func TestCmdGithubSetupBindsAndIsIdempotent(t *testing.T) {
	repoDir := t.TempDir()
	if err := os.Mkdir(filepath.Join(repoDir, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Chdir(repoDir)

	var bindRequest api.InstallBindRequest
	var bindCalls int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.Method == http.MethodGet && r.URL.Path == "/v1/apps/api/github":
			_, _ = w.Write([]byte(`{"connected":true,"installation_id":42,"repo_full_name":"acme/api","production_branch":"main"}`))
		case r.Method == http.MethodPost && r.URL.Path == "/v1/apps/api/github/bind":
			bindCalls++
			if err := json.NewDecoder(r.Body).Decode(&bindRequest); err != nil {
				t.Errorf("decode bind request: %v", err)
			}
			_, _ = w.Write([]byte(`{"binding_id":"bind-1","repo_full_name":"acme/api","production_branch":"trunk"}`))
		default:
			http.NotFound(w, r)
		}
	}))
	defer srv.Close()
	t.Setenv("FAAS_API", srv.URL)
	t.Setenv("FAAS_TOKEN", "fp_live_test")

	oldOut, oldJSON := osStdout, jsonOutput
	var out bytes.Buffer
	osStdout, jsonOutput = &out, false
	t.Cleanup(func() { osStdout, jsonOutput = oldOut, oldJSON })

	args := []string{"api", "--repo", "acme/api", "--production-branch", "trunk", "--deploy-branches", "main=production,staging=staging"}
	if code := cmdGithubSetup(args); code != 0 {
		t.Fatalf("first setup exit = %d, output = %s", code, out.String())
	}
	workflowPath := filepath.Join(repoDir, defaultGithubSetupWorkflow)
	workflow, err := os.ReadFile(workflowPath)
	if err != nil {
		t.Fatalf("read generated workflow: %v", err)
	}
	if !strings.Contains(string(workflow), `- "trunk"`) || strings.Contains(string(workflow), "pull_request:") {
		t.Fatalf("unexpected workflow:\n%s", workflow)
	}
	if bindRequest.InstallationID != 42 || bindRequest.RepoFullName != "acme/api" || bindRequest.ProductionBranch != "trunk" || bindRequest.DeployBranches["main"] != "production" {
		t.Fatalf("bind request = %+v", bindRequest)
	}
	if bindCalls != 1 {
		t.Fatalf("bind calls after first setup = %d", bindCalls)
	}

	out.Reset()
	if code := cmdGithubSetup(args); code != 0 {
		t.Fatalf("idempotent setup exit = %d, output = %s", code, out.String())
	}
	if bindCalls != 2 {
		t.Fatalf("bind calls after second setup = %d", bindCalls)
	}
	workflowAgain, err := os.ReadFile(workflowPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(workflow, workflowAgain) {
		t.Fatal("idempotent setup changed the workflow")
	}
	if !strings.Contains(out.String(), "already matches") {
		t.Fatalf("expected idempotent receipt, got %s", out.String())
	}
}

func TestCmdGithubSetupDryRunDoesNotWriteOrCallAPI(t *testing.T) {
	repoDir := t.TempDir()
	if err := os.Mkdir(filepath.Join(repoDir, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Chdir(repoDir)
	called := false
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		called = true
		http.Error(w, "unexpected network call", http.StatusInternalServerError)
	}))
	defer srv.Close()
	t.Setenv("FAAS_API", srv.URL)
	t.Setenv("FAAS_TOKEN", "fp_live_test")

	oldOut, oldJSON := osStdout, jsonOutput
	var out bytes.Buffer
	osStdout, jsonOutput = &out, false
	t.Cleanup(func() { osStdout, jsonOutput = oldOut, oldJSON })

	if code := cmdGithubSetup([]string{"api", "--repo", "acme/api", "--production-branch", "main", "--rollout", "safe", "--dry-run"}); code != 0 {
		t.Fatalf("dry-run exit = %d, output = %s", code, out.String())
	}
	if called {
		t.Fatal("dry-run made an API request")
	}
	if _, err := os.Stat(filepath.Join(repoDir, defaultGithubSetupWorkflow)); !os.IsNotExist(err) {
		t.Fatalf("dry-run created workflow, stat err = %v", err)
	}
	if !strings.Contains(out.String(), "Generated workflow:") {
		t.Fatalf("dry-run did not show generated workflow: %s", out.String())
	}
	if !strings.Contains(out.String(), `rollout: "safe"`) || !strings.Contains(out.String(), "rollout:            safe") {
		t.Fatalf("dry-run did not show safe rollout mode: %s", out.String())
	}
}
